BINEXT = {'.jpg', '.jpeg', '.png', '.pcap', '.bin', '.raw', '.img', '.zip'}


def _b64(path):
    with open(path, 'rb') as f:
        return base64.b64encode(f.read()).decode()


def _dir(p):
    return {'path': p, 'type': 'dir'}


def _f(p, t):
    return {'path': p, 'text': t}


def _seed_file(src_dir, name, dest):
    """Return an fs entry for file `name` from src_dir at VFS path dest."""
    ext = os.path.splitext(name)[1].lower()
    p = os.path.join(src_dir, name)
    if ext in BINEXT:
        return {'path': dest, 'b64': _b64(p)}
    with open(p, encoding='utf-8') as f:
        return {'path': dest, 'text': f.read()}


def _py_tools(script, output):
    return {'python3': {
        'help': 'python3 <скрипт.py> — интерпретатор Python (вывод захвачен из реального запуска)',
        'cases': [
            {'match': r'--version|^-V$', 'example': 'python3 --version', 'output': 'Python 3.12.4'},
            {'match': script.replace('.', r'\.'), 'example': 'python3 ' + script, 'output': output},
        ],
        'fallback': 'python3: доступно `python3 %s`\n' % script}}


def py_lab(id, category, title, files, script, output, task, hints, flag,
           toolset=('core', 'python3')):
    src = CRYPTO[id]['dir'] if id in CRYPTO else FORENS[id]['dir']
    fs = [_dir(WD), _f(WD + '/task.md', task)]
    for name in files:
        if name == 'task.md':
            continue
        fs.append(_seed_file(src, name, WD + '/' + name))
    return {
        'id': id, 'category': category, 'title': title,
        'toolset': list(toolset), 'workdir': WD, 'files': list(files),
        'check': "grep -q 'nto{' found.txt", 'hints': list(hints),
        'expect': {'file': WD + '/found.txt', 'contains': flag},
        'fs': fs, 'tools': _py_tools(script, output),
    }


